insert into public.task_answers (task_id, symbol, element_name, z, period, grp, block, hint, explanation) values
 (1, 'Na', 'Natri', 11, 3, 1, 's',
  'Hãy viết cấu hình electron theo Z, rồi đếm số lớp electron có electron để xác định chu kỳ.',
  'Z = 11 → 1s² 2s² 2p⁶ 3s¹. Có 3 lớp electron → chu kỳ 3. Lớp ngoài cùng có 1 electron, electron cuối điền vào phân lớp s → khối s, nhóm IA (nhóm 1). Đó là Natri (Na).'),
 (2, 'Mg', 'Magie', 12, 3, 2, 's',
  'Hãy viết cấu hình electron theo Z, rồi đếm số lớp electron có electron để xác định chu kỳ.',
  'Z = 12 → 1s² 2s² 2p⁶ 3s². Có 3 lớp electron → chu kỳ 3. Lớp ngoài cùng có 2 electron, điền vào phân lớp s → khối s, nhóm IIA (nhóm 2). Đó là Magie (Mg).'),
 (3, 'Al', 'Nhôm', 13, 3, 13, 'p',
  'Hãy viết cấu hình electron theo Z, rồi đếm số lớp electron có electron để xác định chu kỳ.',
  'Z = 13 → 1s² 2s² 2p⁶ 3s² 3p¹. Có 3 lớp electron → chu kỳ 3. Lớp ngoài cùng có 3 electron, electron cuối điền vào phân lớp p → khối p, nhóm IIIA (nhóm 13). Đó là Nhôm (Al).'),
 (4, 'S', 'Lưu huỳnh', 16, 3, 16, 'p',
  'Hãy viết cấu hình electron theo Z, rồi đếm số lớp electron có electron để xác định chu kỳ.',
